function wordPressProjectPhaseFailureOutcome(
  error: unknown,
  signal?: AbortSignal,
): KodetyWordPressProjectPhaseOutcome {
  return signal?.aborted || (error instanceof Error && error.name === 'AbortError')
    ? 'aborted'
    : 'error';
}

async function observeWordPressProjectDownloadBody<T>(
  bridge: KodetyWordPressProjectObservabilityBridge | null,
  cache: KodetyWordPressProjectCacheState,
  signal: AbortSignal | undefined,
  readBody: () => Promise<T>,
) {
  const token = bridge?.begin('project_download_body', cache) || null;
  try {
    const result = await readBody();
    bridge?.finish(token, 'ok');
    return result;
  } catch (error) {
    bridge?.finish(token, wordPressProjectPhaseFailureOutcome(error, signal));
    throw error;
  }
}

function observeWordPressProjectDownloadCacheHit(
  bridge: KodetyWordPressProjectObservabilityBridge | null,
) {
  const token = bridge?.begin('project_download_body', 'hit') || null;
  bridge?.finish(token, 'ok');
}

