function previewDownloadFileName(requestedName: string, path: string) {
  const basename = path.replaceAll('\\', '/').split('/').pop() || 'download';
  let decoded = requestedName.trim() || basename;
  try { decoded = decodeURIComponent(decoded); } catch { /* retain authored spelling */ }
  const safe = decoded
    .replace(/[\u0000-\u001f\u007f]/g, '')
    .replace(/[\\/]+/g, '-')
    .trim()
    .slice(0, 240);
  return safe || 'download';
}

function isPublicPreviewDownloadPath(path: string) {
  const segments = path.replaceAll('\\', '/').split('/').filter(Boolean);
  return segments.length > 0
    && segments.every(segment => !segment.startsWith('.'))
    && !segments.some(segment => segment.toLowerCase() === 'node_modules');
}

function downloadPreviewProjectFile(
  file: HtmlProjectFile,
  requestedName: string,
) {
  const bytes = file.data ? Uint8Array.from(file.data) : null;
  const blob = new Blob(
    [bytes ? bytes.buffer : file.text || ''],
    { type: file.mimeType || 'application/octet-stream' },
  );
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement('a');
  anchor.href = url;
  anchor.download = previewDownloadFileName(requestedName, file.path);
  anchor.style.display = 'none';
  document.body.append(anchor);
  anchor.click();
  anchor.remove();
  // WebKit/WebViews may start consuming the object URL after click returns.
  window.setTimeout(() => URL.revokeObjectURL(url), 1000);
}

function downloadPreviewRemoteUrl(url: string, requestedName: string) {
  const anchor = document.createElement('a');
  anchor.href = url;
  anchor.download = previewDownloadFileName(requestedName, url.split(/[?#]/, 1)[0]);
  anchor.target = '_blank';
  anchor.rel = 'noopener noreferrer';
  anchor.style.display = 'none';
  document.body.append(anchor);
  anchor.click();
  anchor.remove();
}

function scopeCssContextToHtmlComponentVariant(
  context: CssEditingContext,
  variantId: string,
): CssEditingContext {
  const selector = context.selector.trim();
  if (context.target !== 'rule' || !selector || !variantId) return context;
  const editorRoot = `body[data-kodety-component-variant-editor="${variantId}"]`;
  const runtimeRoot = `[data-kodety-component-state-variant="${variantId}"]`;
  const rootSelection = /^(?:html|body|:root|(?:html|body)\s*>\s*:first-child)$/i.test(selector);
  return {
    ...context,
    selector: rootSelection
      ? `${editorRoot} > :first-child, ${runtimeRoot}`
      : `${editorRoot} :is(${selector}), ${runtimeRoot}:is(${selector}), ${runtimeRoot} :is(${selector})`,
  };
}

function scopeCssContextToHtmlComponentBundle(
  context: CssEditingContext,
  componentId: string,
): CssEditingContext {
  const selector = context.selector.trim();
  if (context.target !== 'rule' || !selector || !componentId) return context;
  const scope = `[data-kodety-component-scope="${componentId}"]`;
  if (selector.includes('data-kodety-component-scope=')) return context;
  const rootSelection = /^(?:html|body|:root|(?:html|body)\s*>\s*:first-child)$/i.test(selector);
  return {
    ...context,
    selector: rootSelection
      ? scope
      : `${scope}:is(${selector}), ${scope} ${selector}`,
  };
}

function withHtmlComponentVariantCssOverride(
  project: HtmlProject,
  path: string,
  property: string,
  context: CssEditingContext,
) {
  if (!project.mainHtmlPath.startsWith(`${HTML_COMPONENTS_DIRECTORY}/`)) return project;
  const library = normalizeHtmlComponentLibrary(readEditorMetadata(project).components);
  const component = library.components.find(item => (
    item.variants.some(variant => variant.filePath === project.mainHtmlPath)
  ));
  const active = component?.variants.find(variant => variant.filePath === project.mainHtmlPath);
  if (!component || !active || component.variants[0]?.id === active.id) return project;
  const source = project.files[active.filePath]?.text || '';
  const nodeKey = htmlComponentVariantNodeKeyAtPath(source, path);
  if (!nodeKey) return project;
  const overrides = recordHtmlComponentVariantCssOverride(
    recordHtmlComponentVariantReusableClassOverride(active.overrides || {}, nodeKey),
    nodeKey,
    {
      property,
      cssFilePath: context.cssFilePath,
      selector: context.selector,
      pseudo: context.pseudo,
      breakpoint: context.breakpoint,
    },
  );
  if (JSON.stringify(overrides) === JSON.stringify(active.overrides || {})) return project;
  const nextLibrary: HtmlComponentLibrary = {
    version: 1,
    components: library.components.map(item => item.id === component.id
      ? {
          ...item,
          variants: item.variants.map(variant => variant.id === active.id
            ? { ...variant, overrides, inheritanceVersion: 1 }
            : variant),
        }
      : item),
  };
  return updateEditorMetadata(project, metadata => ({
    ...metadata,
    components: nextLibrary,
  }));
}

const wordPressWorkspaceKey = (config: KodetyWordPressConfig) => {
  const raw = config.siteUrl || config.projectUrl || '';
  try {
    const url = new URL(raw, window.location.href);
    return `${url.origin}${url.pathname.replace(/\/+$/, '') || '/'}`;
  } catch {
    return raw.replace(/\/+$/, '');
  }
};

const requestStudioSiteNavigation = (config: KodetyWordPressConfig | undefined): boolean => {
  const studio = config?.studio;
  if (!studio?.enabled || !studio.projectId) return false;
  if (studio.previewUrl) {
    window.open(studio.previewUrl, '_blank', 'noopener,noreferrer');
    return true;
  }
  window.top?.postMessage({
    source: 'kodety-studio-wordpress',
    version: 1,
    type: 'navigate',
    projectId: studio.projectId,
    surface: 'site',
    path: '/',
  }, '*');
  return true;
};

const studioRuntimeRouteUrl = (
  config: KodetyWordPressConfig | undefined,
  route: string,
): string => {
  const base = config?.studio?.enabled ? config.studio.proxyBaseUrl : '';
  if (!base) return '';
  try {
    return new URL(route.replace(/^\/+/, ''), base.endsWith('/') ? base : `${base}/`).toString();
  } catch {
    return '';
  }
};

const currentSnapshotWorkspaceKey = () => {
  const config = wordpressConfig();
  return config ? wordPressWorkspaceKey(config) : '';
};

const wordPressWorkspaceProjectId = (project: HtmlProject) =>
  String(readEditorMetadata(project).projectId || '').trim().toLowerCase();

const localSnapshotMatchesWordPressWorkspace = (
  snapshot: StoredHtmlProject,
  config: KodetyWordPressConfig,
) => {
  const expectedWorkspace = wordPressWorkspaceKey(config);
  if (!expectedWorkspace || snapshot.workspaceKey !== expectedWorkspace) return false;
  const expectedProjectId = config.projectId?.trim().toLowerCase() || '';
  const snapshotProjectId = wordPressWorkspaceProjectId(snapshot.project);
  // Without server identity a cache is recovery-only until the GET establishes
  // authority. An old snapshot must never become editable as a new project.
  return Boolean(expectedProjectId && snapshotProjectId && expectedProjectId === snapshotProjectId);
};

const requestedWordPressStartupProject = (
  project: HtmlProject,
  config: KodetyWordPressConfig,
) => {
  const requestedExperimentId = config.initialExperimentId?.trim();
  const requestedVariantId = config.initialVariantId?.trim();
  if (requestedExperimentId && requestedVariantId) {
    try {
      return openExperimentVariant(project, requestedExperimentId, requestedVariantId).project;
    } catch {
      return project;
    }
  }
  const requested = config.initialHtmlPath;
  if (requested && project.files[requested]?.text !== undefined && /\.html?$/i.test(requested)) {
    return {
      ...project,
      mainHtmlPath: requested,
      previewRootPath: undefined,
    };
  }
  return project;
};

const decodeWordPressProjectHeader = (response: Response, name: string, fallback = '') => {
  const value = response.headers.get(name)?.trim() || '';
  if (!value) return fallback;
  try {
    return decodeURIComponent(value);
  } catch {
    return value;
  }
};

/** Download an authenticated workspace as raw ZIP whenever the host supports
 * it. The legacy base64 REST response remains available for shared/older
 * runtimes, but is too memory-expensive for 70+ MB coded projects. */
async function downloadWordPressProjectSnapshot(
  config: KodetyWordPressConfig,
  cacheMarker: string,
  signal?: AbortSignal,
  cached?: StoredHtmlProject | null,
): Promise<WordPressProjectSnapshot> {
  const binaryDownload = Boolean(config.projectDownloadUrl);
  const url = new URL(config.projectDownloadUrl || config.projectUrl || '', window.location.href);
  url.searchParams.set(cacheMarker, String(Date.now()));
  const reusableCache = cached
    && localSnapshotMatchesWordPressWorkspace(cached, config)
    && Number.isFinite(cached.workspaceRevision)
    && cached.workspaceRevision! >= 0
    && Boolean(cached.workspaceTemplateDigest)
    && Boolean(cached.projectSignature)
    && cached.projectSignature === cached.acknowledgedProjectSignature
      ? cached
      : null;
  const response = await fetch(url, {
    credentials: 'same-origin',
    cache: 'no-store',
    headers: {
      'X-WP-Nonce': config.nonce,
      ...(binaryDownload && reusableCache
        ? {
            'X-Kodety-Known-Workspace-Revision': String(reusableCache.workspaceRevision),
            'X-Kodety-Known-Template-Digest': reusableCache.workspaceTemplateDigest!,
          }
        : {}),
    },
    signal,
  });
  const projectObservability = wordpressProjectObservabilityBridge();
  projectObservability?.start(response.headers.get('X-Kodety-Operation-Id'));
  const bodyCacheState: KodetyWordPressProjectCacheState = reusableCache ? 'miss' : 'bypass';
  if (response.status === 304 && reusableCache) {
    observeWordPressProjectDownloadCacheHit(projectObservability);
    return {
      project: reusableCache.project,
      cssDigest: response.headers.get('X-Kodety-CSS-Digest')?.trim()
        || reusableCache.workspaceCssDigest
        || '',
      workspaceRevision: Number(response.headers.get('X-Kodety-Workspace-Revision'))
        || reusableCache.workspaceRevision
        || 0,
      templateDigest: response.headers.get('X-Kodety-Template-Digest')?.trim()
        || reusableCache.workspaceTemplateDigest
        || '',
      reusedLocalSnapshot: true,
    };
  }
  if (!response.ok) {
    const payload = !binaryDownload
      ? ((await observeWordPressProjectDownloadBody(
          projectObservability,
          bodyCacheState,
          signal,
          () => response.json(),
        ).catch(() => null)) as { message?: string } | null)
      : null;
    throw new Error(
      response.status === 404
        ? 'Importe um projeto ZIP no painel Onun Kodety primeiro.'
        : payload?.message || 'Não foi possível carregar o projeto publicado.',
    );
  }
  if (binaryDownload && reusableCache) {
    const responseWorkspaceRevision = Number(response.headers.get('X-Kodety-Workspace-Revision'));
    const responseTemplateDigest = response.headers.get('X-Kodety-Template-Digest')?.trim() || '';
    if (
      Number.isFinite(responseWorkspaceRevision)
      && responseWorkspaceRevision === reusableCache.workspaceRevision
      && responseTemplateDigest
      && responseTemplateDigest === reusableCache.workspaceTemplateDigest
    ) {
      // Some proxies normalize a conditional 304 to 200 while preserving the
      // authoritative revision headers. Do not inflate and reopen the same ZIP
      // after the cached canvas has already painted.
      await response.body?.cancel().catch(() => undefined);
      observeWordPressProjectDownloadCacheHit(projectObservability);
      return {
        project: reusableCache.project,
        cssDigest: response.headers.get('X-Kodety-CSS-Digest')?.trim()
          || reusableCache.workspaceCssDigest
          || '',
        workspaceRevision: responseWorkspaceRevision,
        templateDigest: responseTemplateDigest,
        reusedLocalSnapshot: true,
      };
    }
  }
  if (binaryDownload) {
    const contentType = response.headers.get('Content-Type')?.toLowerCase() || '';
    if (!contentType.includes('application/zip')) {
      throw new Error('O WordPress não entregou um ZIP válido para o Builder.');
    }
    const archive = await observeWordPressProjectDownloadBody(
      projectObservability,
      bodyCacheState,
      signal,
      () => response.blob(),
    );
    if (archive.size <= 0) throw new Error('O WordPress entregou um projeto vazio.');
    const name = decodeWordPressProjectHeader(response, 'X-Kodety-Original-Name', 'site-kodety.zip');
    const imported = await importZip(new File([archive], name, { type: 'application/zip' }));
    return {
      project: {
        ...imported,
        name:
          decodeWordPressProjectHeader(response, 'X-Kodety-Project-Name', imported.name).trim()
          || imported.name,
      },
      receivedProjectDigest: response.headers.get('X-Kodety-Received-Project-Digest')?.trim() || '',
      receivedProjectId: response.headers.get('X-Kodety-Received-Project-Id')?.trim() || '',
      cssDigest: response.headers.get('X-Kodety-CSS-Digest')?.trim() || '',
      workspaceRevision: Number(response.headers.get('X-Kodety-Workspace-Revision')) || 0,
      templateDigest: response.headers.get('X-Kodety-Template-Digest')?.trim() || '',
      reusedLocalSnapshot: false,
    };
  }
  const payload = (await observeWordPressProjectDownloadBody(
    projectObservability,
    bodyCacheState,
    signal,
    () => response.json(),
  )) as {
    data: string;
    receivedProjectDigest?: string;
    receivedProjectId?: string;
    name?: string;
    projectName?: string;
    cssDigest?: string;
    workspaceRevision?: number;
    templateDigest?: string;
  };
  if (
    reusableCache
    && Number(payload.workspaceRevision) === reusableCache.workspaceRevision
    && payload.templateDigest
    && payload.templateDigest === reusableCache.workspaceTemplateDigest
  ) {
    return {
      project: reusableCache.project,
      cssDigest: payload.cssDigest || reusableCache.workspaceCssDigest || '',
      workspaceRevision: reusableCache.workspaceRevision || 0,
      templateDigest: payload.templateDigest,
      reusedLocalSnapshot: true,
    };
  }
  const imported = await importZip(
    new File([decodeBase64Bytes(payload.data)], payload.name || 'site-kodety.zip', {
      type: 'application/zip',
    }),
  );
  return {
    project: {
      ...imported,
      name: payload.projectName?.trim() || imported.name,
    },
    receivedProjectDigest: payload.receivedProjectDigest || '',
    receivedProjectId: payload.receivedProjectId || '',
    cssDigest: payload.cssDigest || '',
    workspaceRevision: Number(payload.workspaceRevision) || 0,
    templateDigest: payload.templateDigest || '',
    reusedLocalSnapshot: false,
  };
}

